(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--za-sj-prepa-sp-j2-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"za-sj-prepa-sp-j2-idesfm\",\n \"titre\": \"Préparation D.E (J) · J2 Santé publique IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 58,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n   \"sha256\": \"cb2be55f5f842902fef9c9b077099188608658e9c3cd1e6e69a55859b317081f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Santé publique · Prépa D.E J2 (IDE/SFM)\",\n     \"slug\": \"prepa-sp-j2-idesfm\",\n     \"pages\": \"\",\n     \"count\": 58,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Santé publique\",\n     \"source\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"L'accessibilité géographique (AG) est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10%.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"80%.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100%.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"60 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 80%.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"AG = population vivant dans le rayon d'accessibilité / population cible × 100. Pour les consultations curatives, le seuil est de 10 km (5 km pour les autres activités). AG = 6 400 / 8 000 × 100 = 80 % (même résultat sur le semestre : 3 200 / 4 000).\\n\\nSource : Formules santé publique harmonisées, §6 Monitorage (p. 5) ; Cours Santé publique L1, L2, L3 révisé 2025-2026, monitorage, tableau des goulots (« + de 10 km pour les CSC », p. 77)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La population cible semestrielle est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2400 personnes.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1800 personnes.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"6400 personnes.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"4 000 personnes.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 4 000 personnes.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le monitorage porte sur six mois : la population cible du monitorage est la population annuelle divisée par 2. 8 000 / 2 = 4 000 personnes. 2 400, 1 800 et 6 400 sont des numérateurs d'autres indicateurs.\\n\\nSource : Formules santé publique harmonisées, §6 Monitorage, PCM = effectif annuel / 2 (exemple des femmes enceintes, p. 5)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"L'utilisation des service (US) est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"80 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"60 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"70 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 60 %.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"US = personnes ayant eu au moins un contact avec le service / PCM × 100 = 2 400 / 4 000 × 100 = 60 %.\\n\\nSource : Formules santé publique harmonisées, §6 Monitorage, US (p. 5) ; Document révisé L2 2023-2024 validé, définitions du monitorage (p. 82)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La couverture adéquate (CA) est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"45 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"65 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"90 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"85 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 45 %.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"CA = personnes ayant reçu la prestation complète (traitement reçu et payé au prix correct) / PCM × 100 = 1 800 / 4 000 × 100 = 45 %.\\n\\nSource : Formules santé publique harmonisées, §6 Monitorage, CA (p. 5)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La couverture effective (CE) est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"73%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3,7%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"37%\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5,3 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 37%\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"CE = personnes ayant reçu la prestation complète et selon les directives nationales (qualité) / PCM × 100 = 1 500 / 4 000 × 100 = 37,5 %, soit 37 % parmi les options. Le dossier avec médicament périmé fait partie des 300 exclus de la CE.\\n\\nSource : Formules santé publique harmonisées, §6 Monitorage, CE (p. 5) ; DOC-20260911-WA0542, 4.6 La couverture effective (p. 11) Remarque : Le calcul exact donne 37,5 % ; l'option « 37% » est la valeur arrondie.\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspondent aux FR ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"4 000 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1 400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"100 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 400 000 F CFA.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"FR = somme à la banque à la veille du monitorage – recettes des six mois du monitorage déjà déposées = 1 000 000 – 600 000 = 400 000 F CFA. Le solde intègre déjà intérêts et agios : aucune autre correction.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Budgétisation, 5.1 Fonds de réserve (p. 17) ; Formules santé publique harmonisées, §7 (p. 6)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspond à la SAB\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"80 000 F CFA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"8 000 000 F CFA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"600 000 F CFA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"400 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 600 000 F CFA\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La SAB est le total des recettes des six mois du monitorage. La correction nationale de la Prépa DE (les J) retient « 600 000 F CFA », c'est-à-dire le montant des recettes du semestre déjà déposées indiqué dans l'énoncé.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Budgétisation, 5.2 La somme à budgétiser (p. 17-18) ; Formules santé publique harmonisées, §7 SAB = RVME + RCAS (p. 6)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspond aux dépenses de fonctionnement local ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"600 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"300 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"400 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 300 000 F CFA.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"DFL = SAB – DO. Avec SAB = RVME + RCAS = 1 000 000 F CFA et DO = 700 000 F CFA : DFL = 300 000 F CFA.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Budgétisation, 5.3-5.4 (p. 18-19) ; Formules santé publique harmonisées, §7 (p. 6) Remarque : Ce résultat suppose une SAB de 1 000 000 F CFA (voir la question précédente).\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Le plafond de réparation de l'immeuble\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"40 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"60 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"10 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 30 000 F CFA.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les frais de réparation de l'immeuble ne doivent pas excéder 10 % des DFL : 10 % × 300 000 = 30 000 F CFA.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Budgétisation, 5.4 Dépenses de fonctionnement local (p. 18) ; Formules santé publique harmonisées, §7 Im = 10 % × DFL (p. 6)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Le plafond des imprévus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"150 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"10 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"15 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"30 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 15 000 F CFA.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les imprévus (frais bancaires, carburant pour les urgences) ne doivent pas excéder 5 % des DFL : 5 % × 300 000 = 15 000 F CFA. 30 000 correspond au plafond de l'immeuble (10 %).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Budgétisation, 5.4 (p. 18) ; Formules santé publique harmonisées, §7 Imp = 5 % × DFL (p. 6)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le taux d'utilisation du mois écoulé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"80 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"20 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"90 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"10 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 90 %.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"TU = doses administrées / doses sorties × 100 = 180 / 200 × 100 = 90 %.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, formule du taux d'utilisation (p. 10) ; Document révisé L2 2023-2024 validé (p. 45)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le taux de perte correspondant ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"90 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"20 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 10 %.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"TP = (doses sorties – doses administrées) / doses sorties × 100 = (200 – 180) / 200 × 100 = 10 %, ou TP = 100 – TU = 100 – 90.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, formule du taux de perte (p. 10) ; Document révisé L2 2023-2024 validé (p. 45)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel facteur de perte découle de ce taux ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2,00.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1,00.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Environ 1,11.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"0,90.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Environ 1,11.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"FP = 100 / (100 – TP) = 100 / 90 ≈ 1,11. C'est aussi la valeur du tableau pour le DTC-HepB-Hib (Penta). 0,90 est le TU exprimé en fraction, pas un facteur de perte.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des vaccins, facteur de perte et tableau n°3 (p. 9-10)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le besoin réel pour le mois suivant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"280 doses.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"500 doses.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"400 doses.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"520 doses.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 500 doses.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"SS = 25 % × BT = 0,25 × 400 = 100 doses ; BR = BT + SS = 400 + 100 = 500 doses. Le BT donné intègre déjà le facteur de perte : on ne le multiplie pas une seconde fois.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Commande des vaccins, 3.1.2-3.1.3 (p. 11) ; Formules santé publique harmonisées, BR = BT + SS (p. 5)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quelle quantité de doses faut-il commander, sous réserve du conditionnement en flacons ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"500.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"120.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"280.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"380.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 380.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"QC = BR – QS = 500 – 120 = 380 doses (à arrondir ensuite au nombre de flacons entiers).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.1.4 La quantité à commander (p. 11) ; Formules santé publique harmonisées, QC = BR – QS (p. 5)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but principal du COGES est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Associer la communauté à la gestion du centre de santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Remplacer l'État\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sanctionner le personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Construire des hôpitaux universitaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Associer la communauté à la gestion du centre de santé\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La création du Coges répond à la nécessité d'associer la communauté comme membres actifs aux activités de gestion et de fonctionnement du centre de santé.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Composition et fonctionnement du Coges, II. But (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La durée du mandat des membres du COGES est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 ans renouvelables\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"5 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 an\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 3 ans renouvelables\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon l'article 3 du décret n° 93-218, les membres sont désignés pour une durée de trois ans, renouvelable.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, IV. Durée du mandat (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le bureau du COGES comprend :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Président et deux infirmiers\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Président, responsable financier, responsable administratif et technique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Président, maire, préfet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Président, secrétaire, trésorier, un commissaire au compte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Président, responsable financier, responsable administratif et technique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le bureau comprend un président (membre communautaire), un responsable de la gestion financière (membre communautaire) et un responsable de la gestion administrative et technique (infirmier, sage-femme ou travailleur social). Le schéma « secrétaire, trésorier, commissaire aux comptes » est celui d'une association, pas du Coges.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, III. Composition (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le responsable de la gestion financière est chargé :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"De la vaccination\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De la surveillance épidémiologique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De l'enregistrement des recettes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des consultations médicales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. De l'enregistrement des recettes\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Il recueille chaque soir les sommes collectées, enregistre les recettes dans le livret de caisse, les verse à la banque et établit le bilan financier. Les autres options relèvent du personnel de santé.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 8.2 Le responsable de la gestion financière (p. 26)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un indicateur est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une donnée brute\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un rapport annuel\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une opinion\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une variable permettant de mesurer un aspect d'une intervention\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Une variable permettant de mesurer un aspect d'une intervention\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'indicateur est une variable qui permet de mesurer les critères retenus dans le monitorage d'une activité.\\n\\nSource : Document révisé L2 2023-2024 validé, Définitions opérationnelles du monitorage, 2.1 Indicateur (p. 82)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'information sanitaire est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un registre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une fiche de consultation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une donnée contextualisée et utile\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une donnée non traitée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Une donnée contextualisée et utile\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'information représente les données placées dans un contexte significatif et utile pour l'utilisateur final. Une donnée non traitée n'est qu'une donnée (la matière première) ; registre et fiche sont des supports.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion de l'information sanitaire, 1.2-1.4 (p. 29)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La première étape du processus de génération de l'information sanitaire est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La diffusion\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La collecte\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'analyse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'interprétation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La collecte\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le processus commence par la collecte (2.1), puis viennent compilation, transmission, traitement, analyse et interprétation, et enfin la rétro-information.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion de l'information sanitaire, II. Étapes du processus (p. 29-33)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le taux de promptitude est calculé à partir :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des supervisions\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des naissances\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des rapports reçus dans le délai requis\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des consultations\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Des rapports reçus dans le délai requis\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"TP = rapports mensuels d'activités reçus dans le délai requis / rapports attendus × 100.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 2.3.1 Promptitude des rapports (p. 30-31) ; Formules santé publique harmonisées, §8 (p. 6)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétro-information est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un retour des informations vers les producteurs des données\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une analyse statistique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une transmission ascendante\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une sanction administrative\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Un retour des informations vers les producteurs des données\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C'est le retour de l'information produite vers les structures de prestation et de gestion, productrices des données sanitaires. La transmission ascendante est l'inverse (envoi des rapports vers le niveau supérieur).\\n\\nSource : DOC-20260911-WA0542, 2.8 La rétro-information (p. 33)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon l'OMS, le SIS sert à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Recruter du personnel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Construire des centres de santé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Payer les agents\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fournir des renseignements sanitaires pour la prise de décision\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Fournir des renseignements sanitaires pour la prise de décision\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Selon l'OMS, le SIS a pour but de fournir des renseignements et des informations sanitaires permettant de surveiller l'état et les services de santé, afin d'améliorer les décisions de gestion à tous les niveaux.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 1.5 Système d'information sanitaire (p. 29)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le niveau central de gestion des données sanitaires est représenté par :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'ESPC\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le District sanitaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La DIIS\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"l'EPHR\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La DIIS\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Au niveau central, la structure qui gère les données sanitaires est la direction chargée de l'information sanitaire ; elle traite l'information, la met à disposition des décideurs (RASS) et assure la rétro-information. L'ESPC et le district relèvent du niveau périphérique.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 3.4 Au niveau central et IV. Circuit de l'information sanitaire (p. 35-36) Remarque : Le cours la nomme « DIS (Direction de l'Information Sanitaire) » ; l'option du sujet écrit « DIIS ».\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une catastrophe est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un événement sans impact\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une urgence mineure\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une simple vulnérabilité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un événement dépassant la capacité de réaction de la communauté\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Un événement dépassant la capacité de réaction de la communauté\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Une catastrophe est un événement naturel ou causé par l'homme, aux effets négatifs importants, dépassant la capacité de la collectivité affectée à réagir. Une situation d'urgence, elle, reste gérable par la société.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des catastrophes, 1.2 et III (p. 42-43)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le style de supervision adapté aux situations d'urgence est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Autocratique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Laisser-faire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Démocratique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Participatif\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Autocratique\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le style autocratique s'applique aux situations d'urgence qui exigent une décision sans délai et aux situations de blocage. Le style démocratique (ou participatif) s'applique à toutes les situations sauf l'urgence et le blocage.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Supervision, 4.1.3 et 4.2.3 (p. 49-50)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La méthode directe de supervision repose sur :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le questionnaire administratif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le rapport annuel\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'analyse documentaire uniquement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'observation directe du personnel au travail\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. L'observation directe du personnel au travail\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La méthode directe procède par observation directe de l'agent pendant l'exécution d'une tâche. L'interrogatoire des usagers et l'analyse des supports de données relèvent de la méthode indirecte.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Supervision, 6.1 Méthodes (p. 51)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les outils du superviseur figure :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le registre de consultation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La fiche d'observation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le carnet de vaccination\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La carte sanitaire nationale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La fiche d'observation\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La fiche de supervision ou d'observation sert de fil conducteur à l'observation de l'exécution d'une tâche (ex. injection IM). Les autres sont des outils de soins ou de planification.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Supervision, 8.5 La fiche de supervision ou d'observation (p. 53)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le style démocratique de supervision :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Est réservé aux urgences\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Empêche toute initiative\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Repose sur la participation des collaborateurs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Exclut le dialogue\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Repose sur la participation des collaborateurs\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le superviseur fait participer ses collaborateurs à la planification, les aide à décider et encourage leurs initiatives. Il ne s'applique justement pas aux urgences.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Supervision, 4.2 Le style démocratique ou participatif (p. 50)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES est composé exclusivement d'agents de santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : outre l'infirmier, la sage-femme ou le travailleur social, les autres membres sont issus de la communauté (le président et le responsable financier sont des membres communautaires).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, III. Composition (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le décret N°93-218 du 03 février 1993 fixe les règles de gestion des formations sanitaires rurales. Le COGES comprend entre 10 et 20 membres.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : l'article 3 du décret n° 93-218 prévoit un comité de 10 à 20 personnes représentant les communautés villageoises de l'aire sanitaire.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, I et III (p. 22-23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les membres du COGES sont nommés pour un mandat de cinq ans non renouvelables.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le mandat est de trois ans, renouvelable.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, IV. Durée du mandat (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les ASC et les AT font partie d'office du COGES.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les ASC et AT font partie d'office du Coges en raison de leur rôle de relais communautaire.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, III. Nota bene (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La participation aux activités du COGES est rémunérée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la participation aux activités du Coges est du bénévolat.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, III. Nota bene (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un membre du COGES doit résider dans un village desservi par le centre de santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : il faut résider en permanence dans un village desservi par le centre de santé, être de bonne moralité et avoir une activité génératrice de revenu.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, V. Critères (p. 23)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES élabore le budget semestriel du centre de santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : parmi ses rôles dans la gestion financière, le Coges élabore le budget semestriel.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 6.1.1 Rôles dans la gestion financière (p. 24)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES ne joue aucun rôle dans la gestion des ressources humaines.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le Coges veille à la présence du personnel de santé et de soutien, à la qualité de la communication avec les consultants et au savoir-être du personnel.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 6.1.2 Rôles dans la gestion des ressources humaines (p. 24)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES veille à la disponibilité des médicaments essentiels et des vaccins.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : c'est l'un de ses rôles dans la gestion du matériel, des médicaments et du local.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 6.1.3 (p. 24)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES peut promouvoir l'acceptabilité des services offerts à la population.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : en dehors du centre, le Coges fait connaître les activités, promeut la participation financière et l'acceptabilité des services offerts.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 6.2 Rôle en dehors du centre (p. 25)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le responsable de la gestion financière tient le livret de caisse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le livret de caisse, pour noter les recettes et les dépenses du centre, fait partie de ses outils de gestion.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 7-2 Outils du responsable de la gestion financière (p. 25)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le président du COGES coordonne les activités du comité.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le président ouvre le compte du centre, convoque les réunions, autorise les retraits et coordonne les activités du Coges.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 8.1 Le président (p. 25)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les dons et legs constituent une source de revenus du COGES.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les sources de revenus sont les actes de santé, la vente de certains documents (carnets, cartes) et les dons et legs.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 9-1 Sources de revenus (p. 27)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les dépenses liées à l'eau et à l'électricité peuvent être prises en charge par le COGES.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : l'article 7 du décret n° 93-218 cite la consommation d'eau et d'électricité parmi les dépenses des comités de gestion ; le Coges décide aussi du paiement de ces factures.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Coges, 6.1.1 et 9-2 Domaines de dépenses (p. 24, 27)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un indicateur est une variable quantitative ou qualitative mesurant un aspect d'une intervention.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : l'indicateur est une variable qui permet de mesurer les critères retenus dans le suivi d'une activité.\\n\\nSource : Document révisé L2 2023-2024 validé, 2.1 Indicateur (p. 82)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les données sont déjà des informations interprétées.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la donnée est l'input, la matière première ; c'est sa transformation qui produit l'information utile aux décideurs.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion de l'information sanitaire, 1.2 Donnée et 1.3 Information (p. 29)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'information sanitaire est le résultat du traitement et de l'analyse des données\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : l'information est le résultat de la transformation des données en faits utiles pour les décideurs.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 1.3 Information (p. 29)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La collecte des données sanitaires consiste à enregistrer les données dans les registres et rapports.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la collecte consiste à enregistrer toutes les données dans les registres d'activités puis à les reporter dans les fiches de rapport mensuel ou annuel.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 2.1 La collecte des données sanitaires (p. 29)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rapport mensuel des ESPC doit être transmis au district sanitaire au plus tard le 5 du mois suivant.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : dans les ESPC, le rapport mensuel d'activités est transmis au responsable du CSE du district sanitaire au plus tard le 5 du mois suivant (le 10 pour l'hôpital général).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 2.3.1 Promptitude des rapports (p. 30-31)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le taux de complétude mesure la proportion de rapports reçus parmi ceux attendus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : TC = rapports d'activités reçus par le responsable du CSE / rapports attendus × 100, quel que soit le délai de réception.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, 2.3.2 Complétude des rapports (p. 31)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétro-information correspond au retour des informations produites vers les niveaux inférieurs.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la rétro-information est le retour de l'information produite vers les structures des niveaux primaires et secondaires, productrices des données.\\n\\nSource : DOC-20260911-WA0542, 2.8 La rétro-information (p. 33)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une catastrophe est un événement dont les effets dépassent les capacités de réaction de la communauté.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : c'est la définition du cours (effets négatifs importants dépassant la capacité de la collectivité affectée à réagir).\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des catastrophes, 1.2 Catastrophe (p. 42)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le risque est indépendant du danger et de la vulnérabilité.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le risque est la probabilité de pertes à la suite d'un événement défavorable, vu le danger et la vulnérabilité ; il en dépend directement.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Gestion des catastrophes, 1.5 Risque (p. 43)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les tremblements de terre sont des catastrophes naturelles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le cours cite les cyclones, les tremblements de terre et les tsunamis parmi les catastrophes naturelles.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, IV. Différents types de catastrophes naturelles (p. 43)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__55\",\n       \"num\": \"56\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des rôles de l'infirmier en cas de catastrophe est de donner l'alerte.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : son rôle principal est de donner l'alerte au directeur départemental de la santé pour organiser les secours, et d'apporter un soutien psychologique à la communauté avant leur arrivée.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, VI. Rôles de l'infirmier et de la sage-femme (p. 44)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__56\",\n       \"num\": \"57\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La supervision vise l'amélioration des compétences et du rendement du personnel.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la supervision promeut l'amélioration continue de la performance ; son issue est l'amélioration de la compétence, de la qualité du service et du rendement.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Supervision, II. Buts et III. Tableau des différences (p. 48-49)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j2-idesfm__57\",\n       \"num\": \"58\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La supervision est généralement une activité annoncée et périodique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : dans le tableau comparatif, la supervision est « annoncée et périodique », contrairement à l'inspection (programmée ou à l'improviste) et au contrôle (à tout moment). La phase préparatoire prévoit d'ailleurs un calendrier communiqué à temps.\\n\\nSource : Cours Santé publique L1, L2, L3 révisé 2025-2026, Supervision, III. Tableau et 9.1 Phase préparatoire (p. 49, 53)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SANTE_PUBLIQUE_IDE_SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
